mapper.insert:

        SELECT COALESCE(MAX(CATEGORYID), 0) + 1 FROM ACC_CATEGORY WHERE USERID = #{USERID}


	INSERT INTO ACC_CATEGORY (
		USERID
	  , CATEGORYID
	  , USAGENM
	  , CATEGORYNM
	  , CATEGORYDETAILNM
	  , CLASSIFICATION
	  , REGID
	  , REGDATE
	  , MODID
	  , MODDATE
	) VALUES (
		#{USERID}
	  , #{CATEGORYID}
	  , #{USAGENM}
	  , #{CATEGORYNM}
	  , #{CATEGORYDETAILNM}
	  , #{CLASSIFICATION}
	  , #{REGID}
	  , NOW()
	  , null
	  , null
	)

mapper.update:
		UPDATE ACC_CATEGORY
		   SET USAGENM = #{USAGENM}
    		 , CATEGORYNM = #{CATEGORYNM}
             , CATEGORYDETAILNM = #{CATEGORYDETAILNM}
             , CLASSIFICATION = #{CLASSIFICATION}
             , MODID = #{USERID}
             , MODDATE = NOW()
         WHERE USERID = #{USERID}
           AND CATEGORYID = #{CATEGORYID}

mapper.delete:
DELETE FROM ACC_CATEGORY
 WHERE USERID = #{USERID}
   AND CATEGORYID = #{CATEGORYID}

