AND BANKNM LIKE CONCAT('%', #{searchValue}, '%')
AND ACCOUNTNUM LIKE CONCAT('%', #{searchValue}, '%')
ORDER BY BANKNM, ACCOUNTNUM LIMIT #{offset}, #{limit}

SELECT COUNT(*) AS CNT FROM ACC_ACCOUNT WHERE USERID = #{USERID}
AND BANKNM LIKE CONCAT('%', #{searchValue}, '%')
AND ACCOUNTNUM LIKE CONCAT('%', #{searchValue}, '%')

