        SELECT COALESCE(MAX(HISTORYID), 0) + 1 FROM ACC_SAVINGS_HISTORY WHERE USERID = #{USERID} AND SAVINGSID = #{SAVINGSID}

	INSERT INTO ACC_SAVINGS_HISTORY (
		HISTORYID
	  , SAVINGSID
	  , USERID
	  , PAYAMOUNT
	  , TYPE
	  , IS_PAID
	  , PAYMONTH
	  , REGID
	  , REGDATE
	) VALUES (
		#{HISTORYID}
	  , #{SAVINGSID}
	  , #{USERID}
	  , #{PAYAMOUNT}
	  , 'R' /* 정기납입 */
	  , 'N'
	  , #{PAYMONTH}
	  , #{USERID}
	  , NOW()
	)

mapper.delete:
DELETE FROM ACC_SAVINGS
      WHERE USERID = #{USERID}
        AND SAVINGSID = #{SAVINGSID}

DELETE FROM ACC_SAVINGS_HISTORY
      WHERE USERID = #{USERID}
        AND SAVINGSID = #{SAVINGSID}

mapper.select:
SELECT HISTORYID , SAVINGSID , USERID , PAYDATE , PAYAMOUNT , TYPE , IS_PAID , PAYMONTH , MEMO , CASE WHEN PAYMONTH <= DATE_FORMAT(NOW(), '%Y-%m') THEN 'Y' ELSE 'N' END AS IS_CURRENT FROM ACC_SAVINGS_HISTORY WHERE USERID = #{USERID} AND SAVINGSID = #{SAVINGSID}
AND TYPE = #{TYPE}
ORDER BY PAYMONTH ASC

mapper.update:
		UPDATE ACC_SAVINGS_HISTORY
		   SET IS_PAID = CASE WHEN IS_PAID = 'Y' THEN 'N' ELSE 'Y' END
             , PAYDATE = CASE WHEN IS_PAID = 'Y' THEN NOW() ELSE NULL END
		 WHERE USERID = #{USERID}
		   AND SAVINGSID = #{SAVINGSID}
		   AND HISTORYID = #{HISTORYID}

mapper.insert:

        SELECT COALESCE(MAX(HISTORYID), 0) + 1 FROM ACC_SAVINGS_HISTORY WHERE USERID = #{USERID} AND SAVINGSID = #{SAVINGSID}

	INSERT INTO ACC_SAVINGS_HISTORY (
		HISTORYID
	  , SAVINGSID
	  , USERID
	  , PAYDATE
	  , PAYAMOUNT
	  , TYPE
	  , IS_PAID
	  , PAYMONTH
	  , MEMO
	  , REGID
	  , REGDATE
	) VALUES (
		#{HISTORYID}
	  , #{SAVINGSID}
	  , #{USERID}
	  , #{PAYDATE}
	  , #{PAYAMOUNT}
	  , 'A'
	  , 'Y'
	  , LEFT(#{PAYDATE}, 7)
	  , #{MEMO}
	  , #{USERID}
	  , NOW()
	)

mapper.delete:
DELETE FROM ACC_SAVINGS_HISTORY
      WHERE USERID = #{USERID}
        AND SAVINGSID = #{SAVINGSID}
        AND HISTORYID = #{HISTORYID}
